"""The private peer wire carries bounded opaque frames, never Home credentials."""


import base64
import hashlib
import json
import os
import socket
import struct
import threading

WINDOW = 64 * 1024
CHUNK = 16 * 1024
PEER_HOST = "home-peer.internal"


class PeerRefused(RuntimeError):
    pass


class PeerWire:
    def __init__(self, connection: socket.socket):
        self.connection = connection
        self.reader = connection.makefile("rb")
        self.write_lock = threading.Lock()

    @classmethod
    def connect(cls, ordinal: int) -> "PeerWire":
        connection = socket.create_connection((PEER_HOST, 80), timeout=10)
        wire = cls(connection)
        try:
            nonce = base64.b64encode(os.urandom(16)).decode("ascii")
            connection.sendall((
                f"GET /peer/{ordinal} HTTP/1.1\r\nHost: {PEER_HOST}\r\n"
                "Upgrade: websocket\r\nConnection: Upgrade\r\n"
                f"Sec-WebSocket-Key: {nonce}\r\nSec-WebSocket-Version: 13\r\n\r\n"
            ).encode("ascii"))
            if wire.reader.readline(1024).split()[:2] != [b"HTTP/1.1", b"101"]:
                raise PeerRefused("peer handshake refused")
            headers: dict[bytes, bytes] = {}
            for _ in range(32):
                line = wire.reader.readline(1024)
                if line == b"\r\n":
                    break
                if not line.endswith(b"\r\n") or b":" not in line:
                    raise PeerRefused("invalid peer handshake")
                key, value = line.split(b":", 1)
                key = key.strip().lower()
                if key in headers:
                    raise PeerRefused("duplicate peer header")
                headers[key] = value.strip()
            else:
                raise PeerRefused("peer handshake too large")
            expected = base64.b64encode(hashlib.sha1(
                (nonce + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode("ascii")
            ).digest())
            if (headers.get(b"sec-websocket-accept") != expected
                    or headers.get(b"upgrade", b"").lower() != b"websocket"
                    or b"upgrade" not in headers.get(b"connection", b"").lower().split(b", ")):
                raise PeerRefused("invalid peer upgrade")
            connection.settimeout(None)
            return wire
        except BaseException:
            wire.close()
            raise

    def exact(self, size: int) -> bytes:
        data = self.reader.read(size)
        if len(data) != size:
            raise PeerRefused("peer disconnected")
        return data

    def receive(self) -> tuple[int, bytes]:
        while True:
            first, second = self.exact(2)
            opcode = first & 15
            if first & 0xF0 != 0x80 or second & 0x80:
                raise PeerRefused("invalid peer frame")
            size = second & 127
            if size == 126:
                size = struct.unpack("!H", self.exact(2))[0]
            elif size == 127:
                raise PeerRefused("peer frame too large")
            limit = CHUNK if opcode == 2 else 64 if opcode == 1 else 125
            if size > limit or opcode not in (1, 2, 8, 9, 10):
                raise PeerRefused("invalid peer frame")
            body = self.exact(size)
            if opcode == 8:
                raise PeerRefused("peer closed")
            if opcode == 9:
                self.send(10, body)
            elif opcode != 10:
                return opcode, body

    def send(self, opcode: int, body: bytes) -> None:
        if len(body) > (CHUNK if opcode == 2 else 125):
            raise PeerRefused("peer frame too large")
        mask = os.urandom(4)
        size = len(body)
        header = bytes([0x80 | opcode, 0x80 | size]) if size < 126 else (
            bytes([0x80 | opcode, 0xFE]) + struct.pack("!H", size)
        )
        masked = bytes(value ^ mask[index % 4] for index, value in enumerate(body))
        with self.write_lock:
            self.connection.sendall(header + mask + masked)

    def control(self, value: dict[str, int | bool]) -> None:
        self.send(1, json.dumps(value, separators=(",", ":")).encode("ascii"))

    def close(self) -> None:
        try:
            self.connection.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        self.connection.close()
        self.reader.close()

"""Loopback Home identities route to named runtimes through the private peer binding."""


import json
import selectors
import socket
import threading
from collections.abc import Callable


FIRST_PORT = 20000
MAX_ORDINAL = 128
MAX_CONNECTIONS = 256


def peer_port(ordinal: int) -> int:
    if not 0 <= ordinal <= MAX_ORDINAL:
        raise PeerRefused("invalid Home ordinal")
    return 8327 if ordinal == 0 else FIRST_PORT + ordinal


def pipe_local(local: socket.socket, remote: socket.socket) -> None:
    def forward(source: socket.socket, destination: socket.socket) -> None:
        try:
            while True:
                body = source.recv(CHUNK)
                if not body:
                    destination.shutdown(socket.SHUT_WR)
                    return
                destination.sendall(body)
        except OSError:
            for connection in (source, destination):
                try:
                    connection.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass

    outgoing = threading.Thread(target=forward, args=(local, remote), daemon=True)
    outgoing.start()
    forward(remote, local)
    outgoing.join()


def pipe_peer(local: socket.socket, wire: PeerWire) -> None:
    condition = threading.Condition()
    pending = bytearray()
    credit = 0
    outstanding = 0
    stopped = False
    sent_fin = False
    received_fin = False
    wrote_fin = False

    def stop() -> None:
        nonlocal stopped
        with condition:
            if stopped:
                return
            stopped = True
            condition.notify_all()
        try:
            local.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        wire.close()

    def send_tcp() -> None:
        nonlocal credit, sent_fin
        try:
            while True:
                with condition:
                    condition.wait_for(lambda: stopped or credit > 0)
                    if stopped:
                        return
                    size = min(credit, CHUNK)
                body = local.recv(size)
                if not body:
                    wire.control({"fin": True})
                    with condition:
                        sent_fin = True
                        finished = wrote_fin
                    if finished:
                        stop()
                    return
                with condition:
                    credit -= len(body)
                wire.send(2, body)
        except (OSError, PeerRefused):
            stop()

    def write_tcp() -> None:
        nonlocal outstanding, wrote_fin
        try:
            while True:
                with condition:
                    condition.wait_for(lambda: stopped or pending or received_fin)
                    if stopped:
                        return
                    body = bytes(pending[:CHUNK])
                    del pending[:len(body)]
                if not body:
                    local.shutdown(socket.SHUT_WR)
                    with condition:
                        wrote_fin = True
                        finished = sent_fin
                    if finished:
                        stop()
                    return
                local.sendall(body)
                with condition:
                    outstanding -= len(body)
                wire.control({"credit": len(body)})
        except (OSError, PeerRefused):
            stop()

    sender = threading.Thread(target=send_tcp, daemon=True)
    writer = threading.Thread(target=write_tcp, daemon=True)
    sender.start()
    writer.start()
    try:
        wire.control({"credit": WINDOW})
        while not stopped:
            opcode, body = wire.receive()
            if opcode == 2:
                with condition:
                    if received_fin or not body or len(body) > WINDOW - outstanding:
                        raise PeerRefused("peer receive window exceeded")
                    outstanding += len(body)
                    pending.extend(body)
                    condition.notify_all()
                continue
            message = json.loads(body)
            if not isinstance(message, dict) or len(message) != 1:
                raise PeerRefused("invalid peer control")
            if "credit" in message:
                amount = message["credit"]
                with condition:
                    if type(amount) is not int or not 1 <= amount <= WINDOW - credit:
                        raise PeerRefused("peer credit exceeded")
                    credit += amount
                    condition.notify_all()
            elif message == {"fin": True} and not received_fin:
                with condition:
                    received_fin = True
                    condition.notify_all()
            else:
                raise PeerRefused("invalid peer control")
    except (OSError, ValueError, PeerRefused):
        pass
    finally:
        stop()
        sender.join()
        writer.join()


class HomePeers:
    def __init__(self, own_ordinal: int, connect: Callable[[int], PeerWire] = PeerWire.connect):
        peer_port(own_ordinal)
        self.connect = connect
        self.own_ordinal = own_ordinal
        self.listeners: list[socket.socket] = []
        self.connections: set[socket.socket] = set()
        self.lock = threading.Lock()
        self.closed = False
        self.wakeup: tuple[socket.socket, socket.socket] | None = None

    def start(self) -> None:
        try:
            for ordinal in range(MAX_ORDINAL + 1):
                # The legacy Home already owns its original loopback address.
                if ordinal == 0 and self.own_ordinal == 0:
                    continue
                listener = socket.create_server(("127.0.0.1", peer_port(ordinal)), backlog=16)
                self.listeners.append(listener)
            self.wakeup = socket.socketpair(socket.AF_UNIX, socket.SOCK_STREAM)
            threading.Thread(target=self.accept, daemon=True).start()
        except BaseException:
            self.close()
            raise

    def accept(self) -> None:
        assert self.wakeup is not None
        try:
            with selectors.DefaultSelector() as selected:
                selected.register(self.wakeup[0], selectors.EVENT_READ, None)
                ordinals = [n for n in range(MAX_ORDINAL + 1) if n != 0 or self.own_ordinal != 0]
                for listener, ordinal in zip(self.listeners, ordinals):
                    selected.register(listener, selectors.EVENT_READ, ordinal)
                while not self.closed:
                    for ready, _ in selected.select():
                        if ready.data is None or self.closed:
                            return
                        if not isinstance(ready.fileobj, socket.socket):
                            raise OSError("invalid peer listener")
                        local, _ = ready.fileobj.accept()
                        with self.lock:
                            if self.closed or len(self.connections) >= MAX_CONNECTIONS:
                                local.close()
                                continue
                            self.connections.add(local)
                        threading.Thread(target=self.serve, args=(local, ready.data), daemon=True).start()
        except OSError:
            self.close()
        finally:
            for connection in self.wakeup:
                connection.close()

    def serve(self, local: socket.socket, ordinal: int) -> None:
        remote = None
        try:
            if ordinal == self.own_ordinal:
                remote = socket.create_connection(("127.0.0.1", 8329), timeout=10)
                remote.settimeout(None)
                with self.lock:
                    if self.closed:
                        return
                    self.connections.add(remote)
                pipe_local(local, remote)
            else:
                pipe_peer(local, self.connect(ordinal))
        except (OSError, PeerRefused):
            pass
        finally:
            local.close()
            if remote:
                remote.close()
            with self.lock:
                self.connections.discard(local)
                if remote:
                    self.connections.discard(remote)

    def close(self) -> None:
        with self.lock:
            self.closed = True
            if self.wakeup:
                try:
                    self.wakeup[1].send(b"x")
                except OSError:
                    pass
            for connection in [*self.listeners, *self.connections]:
                try:
                    connection.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass
                connection.close()

"""The retained Home can add private peers without replacing its serving process."""


import json
import os
from pathlib import Path
import signal
import sys
import threading


WITNESS = Path("/dev/shm/cliproxy-pool/home-peer-start.json")


def main() -> None:
    options = json.loads(sys.argv[1])
    if (set(options) != {"sourceSha", "nonce", "bootId"}
            or any(not isinstance(value, str) or not value or len(value) > 256
                   for value in options.values())):
        raise ValueError("invalid peer bootstrap binding")
    status = Path("/proc/self/stat").read_text()
    record = {
        **options,
        "pid": os.getpid(),
        "startTicks": status[status.rfind(")") + 2:].split()[19],
        "ready": False,
    }
    # A second exec on this incarnation cannot start another listener, even after a lost reply.
    with os.fdopen(os.open(WITNESS, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "w") as output:
        json.dump(record, output)
    stopped = threading.Event()
    signal.signal(signal.SIGTERM, lambda *_: stopped.set())
    signal.signal(signal.SIGINT, lambda *_: stopped.set())
    peers = HomePeers(0)
    try:
        peers.start()
        record["ready"] = True
        temporary = WITNESS.with_suffix(".ready")
        with os.fdopen(os.open(temporary, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "w") as output:
            json.dump(record, output)
        os.replace(temporary, WITNESS)
        print(json.dumps(record, separators=(",", ":")), flush=True)
        stopped.wait()
    finally:
        peers.close()


if __name__ == "__main__":
    main()
